  1	import AVFoundation
  2	
  3	/// Where `ExportEncodePump`'s packets go, once the pump has made them the container's bytes
  4	/// (AV1's temporal delimiters stripped) and put them in order (spec §11 CX-12, CX-15, CX-16):
  5	/// the MP4 row's passthrough `AVAssetWriterInput`, or the WebM rows' core writer. Both are called on the pump's encode
  6	/// queue alone, so a sink needs no lock of its own.
  7	protocol ExportPacketSink: AnyObject {
  8	    /// Writes one packet presented at `time` for `duration`; `key` is a KEY_FRAME; `alpha` is
  9	    /// the frame's alpha stream packet on `vp9_alpha_webm` (CX-17 (5)), else nil. nil once
 10	    /// written; `ExportPacketSinkStopped` when the export stopped first (nothing to report);
 11	    /// any other error fails the export.
 12	    func append(
 13	        _ data: Data, alpha: Data?, at time: CMTime, duration: CMTime, key: Bool,
 14	        isStopping: () -> Bool
 15	    ) -> (any Error)?
 16	    /// No packet follows: the pump's one exit calls it exactly once, clean or not.
 17	    func finish()
 18	}
 19	
 20	/// A sink's answer when the export stopped while it waited: the stop is already recorded
 21	/// (a cancel, or another pump's failure), so the pump reports nothing for it.
 22	struct ExportPacketSinkStopped: Error {}
 23	
 24	/// The `av1` row's sink: each packet as one `av01` sample (`ExportAV1Track.sample`) into the
 25	/// passthrough input, after waiting for it to take more; `finish` marks the input finished.
 26	final class ExportMP4PacketSink: ExportPacketSink {
 27	    private let input: AVAssetWriterInput
 28	    /// The `av01` description; nil (never on the `av1` row) makes every packet unwritable.
 29	    private let format: CMVideoFormatDescription?
 30	
 31	    init(input: AVAssetWriterInput, format: CMVideoFormatDescription?) {
 32	        self.input = input
 33	        self.format = format
 34	    }
 35	
 36	    @available(*, unavailable) required init?(coder: NSCoder) {
 37	        fatalError("ExportMP4PacketSink does not support NSCoder")
 38	    }
 39	
 40	    func append(
 41	        _ data: Data, alpha: Data?, at time: CMTime, duration: CMTime, key: Bool,
 42	        isStopping: () -> Bool
 43	    ) -> (any Error)? {
 44	        // An MP4 has nowhere to put a VP9 alpha (CX-1: no VP9 in MP4).
 45	        guard alpha == nil else {
 46	            return Exporter.ExportError.failed("An MP4 cannot carry a packet's alpha.")
 47	        }
 48	        guard let format, let sample = ExportAV1Track.sample(
 49	            data, at: time, duration: duration, format: format)
 50	        else {
 51	            return Exporter.ExportError.failed("An AV1 packet could not be made a sample.")
 52	        }
 53	        while !input.isReadyForMoreMediaData {
 54	            guard !isStopping() else { return ExportPacketSinkStopped() }
 55	            usleep(1000)
 56	        }
 57	        guard input.append(sample) else {
 58	            return Exporter.ExportError.failed("The file could not be written.")
 59	        }
 60	        return nil
 61	    }
 62	
 63	    func finish() {
 64	        input.markAsFinished()
 65	    }
 66	}
 67	
 68	/// The WebM rows' sink: each packet into the core's writer as the video track's block at its
 69	/// time in nanoseconds, the key flag the encoder's (spec §11 CX-15 (3), CX-16 (6)), with its
 70	/// alpha on `vp9_alpha_webm` (CX-17 (5)). The core queues
 71	/// what the interleave holds back, so this never waits. `finish` ends the video track; a
 72	/// failure there is the writer's `finish`'s to report.
 73	final class ExportWebMPacketSink: ExportPacketSink {
 74	    private let webm: ReelWebM
 75	    /// `-RCDevWebMFault video@N` (`ExportWebMDevFault`, dev tools only), else nil.
 76	    private let fault: ExportWebMDevFault?
 77	    private var packets = 0
 78	
 79	    init(webm: ReelWebM, fault: ExportWebMDevFault? = nil) {
 80	        self.webm = webm
 81	        self.fault = fault
 82	    }
 83	
 84	    @available(*, unavailable) required init?(coder: NSCoder) {
 85	        fatalError("ExportWebMPacketSink does not support NSCoder")
 86	    }
 87	
 88	    func append(
